        border-radius: 999px;
        background: var(--text);
        color: #fff;
        text-decoration: none;
        z-index: 20;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .shell {
        width: min(100% - 2rem, var(--content-width));
        margin: 0 auto;
      }

      .topbar {
        position: sticky;
        top: 0;
        z-index: 10;
        backdrop-filter: blur(20px);
        background: color-mix(in srgb, var(--bg) 88%, transparent);
        border-bottom: 1px solid var(--border);
      }

      .topbar__inner {
