      .brand__mark {
        display: grid;
        place-items: center;
        width: 2.5rem;
        aspect-ratio: 1;
        border-radius: 14px;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), #2dd4bf);
        box-shadow: 0 12px 30px rgba(15, 118, 110, 0.28);
      }

      .brand__name {
        font-size: 1rem;
      }

      .brand__tagline {
        display: block;
        font-size: 0.78rem;
        font-weight: 600;
        color: var(--muted);
      }

      .primary-nav ul,
      .footer-nav ul,
      .meta-list,
      .feature-list,
      .deal-list {
        list-style: none;
        margin: 0;
        padding: 0;
