      .primary-nav ul {
        display: flex;
        gap: 1.25rem;
        align-items: center;
        flex-wrap: wrap;
      }

      .primary-nav a,
      .footer-nav a {
        text-decoration: none;
        color: var(--muted);
        font-weight: 650;
