      main {
        display: block;
      }

      .hero {
        padding: 2.5rem 0 1.5rem;
      }

      .hero__panel {
        position: relative;
        overflow: clip;
        border: 1px solid var(--border);
        border-radius: var(--radius-xl);
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.88), rgba(255, 255, 255, 0.68)),
