        min-height: 3rem;
        padding: 0.8rem 1.15rem;
        border-radius: 999px;
        border: 1px solid transparent;
        text-decoration: none;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
      }

      .button--primary {
        background: var(--accent);
        color: #fff;
