      .button--secondary:hover {
        border-color: rgba(31, 35, 40, 0.24);
      }

      .hero-card {
        border-radius: var(--radius-lg);
        background: rgba(255, 255, 255, 0.78);
        border: 1px solid rgba(31, 35, 40, 0.1);
