      .story-item p {
        margin-bottom: 0.7rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .story-item a {
        color: var(--accent-strong);
        text-decoration: none;
        font-weight: 700;
      }

      .status-bar {
        margin: 1.5rem 0 0;
        padding: 0.95rem 1rem;
        border-radius: var(--radius-md);
        border: 1px solid var(--border);
        background: var(--surface);
        color: var(--muted);
