      .footer {
        margin-top: 2rem;
        padding: 1.75rem 0 2.5rem;
        border-top: 1px solid var(--border);
      }

      .footer__grid {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        flex-wrap: wrap;
      }

      .footer__copy {
        color: var(--muted);
        margin: 0;
      }

      .footer-nav ul {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      .icon {
        width: 1rem;
        height: 1rem;
        flex-shrink: 0;
      }

      @media (max-width: 980px) {
        .topbar__inner,
        .hero__grid,
        .section__header,
        .footer__grid {
          grid-template-columns: 1fr;
          flex-direction: column;
          align-items: start;
        }

        .feature-list,
        .deal-list,
        .editorial-grid {
          grid-template-columns: 1fr 1fr;
