        .topbar,
        .hero__panel,
        .product-card,
        .deal-card,
        .editorial-card,
        .story-item,
        .status-bar,
        .cart-pill {
          forced-color-adjust: auto;
          background: Canvas;
          color: CanvasText;
          border-color: CanvasText;
          box-shadow: none;
        }

        .button--primary,
        .brand__mark,
        .deal-savings,
        .eyebrow,
        .meta-list li {
          forced-color-adjust: auto;
          background: Canvas;
          color: CanvasText;
          border: 1px solid CanvasText;
        }
      }
    </style>
