const { chromium } = require('playwright');
(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const result = await page.evaluate(async () => await window.axe.run());
  const violations = result.violations.map(v => ({ id: v.id, impact: v.impact, tags: v.tags, targets: v.nodes.map(n => n.target) }));
  console.log(JSON.stringify(violations, null, 2));
  await browser.close();
  process.exit(result.violations.some(v => !v.tags.includes('best-practice')) ? 1 : 0);
})();
