           linear-gradient(145deg, rgba(15, 118, 110, 0.12), rgba(180, 83, 9, 0.12));
         box-shadow: var(--shadow);
         padding: clamp(1.5rem, 3vw, 2.5rem);
       }

       .hero__grid {
         display: grid;
         grid-template-columns: minmax(0, 1.2fr) minmax(270px, 0.8fr);
         gap: 2rem;
         align-items: center;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         padding: 0.45rem 0.8rem;
         border-radius: 999px;
         background: var(--accent-soft);
         color: var(--accent-strong);
         font-weight: 700;
         font-size: 0.9rem;
         margin: 0 0 1rem;
       }

       h1,
       h2,
       h3,
       p {
         margin-top: 0;
       }

       h1 {
         font-size: clamp(2.4rem, 5vw, 4.8rem);
         line-height: 0.96;
         letter-spacing: -0.04em;
         margin-bottom: 1rem;
         max-width: 11ch;
       }

       .lead {
         font-size: clamp(1.05rem, 1.8vw, 1.22rem);
         max-width: 56ch;
         color: var(--muted);
         margin-bottom: 1.5rem;
       }

       .hero__actions {
         display: flex;
         gap: 0.9rem;
         flex-wrap: wrap;
       }

       .button {
         display: inline-flex;
         align-items: center;
         justify-content: center;
         gap: 0.55rem;
         min-height: 3rem;
         padding: 0.8rem 1.15rem;
         border-radius: 999px;
         border: 1px solid transparent;
         text-decoration: none;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
       }

       .button--primary {
         background: var(--accent);
         color: #fff;
       }

       .button--primary:hover {
         background: var(--accent-strong);
       }

       .button--secondary {
         background: var(--surface);
         color: var(--text);
         border-color: var(--border);
       }

       .button--secondary:hover {
         border-color: rgba(31, 35, 40, 0.24);
       }

       .hero-card {
         border-radius: var(--radius-lg);
         background: rgba(255, 255, 255, 0.78);
         border: 1px solid rgba(31, 35, 40, 0.1);
         padding: 1.25rem;
       }

       .hero-card__visual {
         border-radius: 22px;
         overflow: hidden;
         background: linear-gradient(135deg, #0f766e, #d97706);
         aspect-ratio: 4 / 3;
         display: grid;
         place-items: center;
         color: #fff;
       }

       .hero-card__stat {
         display: flex;
         justify-content: space-between;
         gap: 1rem;
         margin-top: 1rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .section {
         padding: 1.5rem 0 0;
       }

       .section__header {
         display: flex;
         align-items: end;
         justify-content: space-between;
         gap: 1rem;
         margin-bottom: 1rem;
       }

       .section__title {
         font-size: clamp(1.5rem, 2.6vw, 2.1rem);
         margin-bottom: 0.3rem;
         letter-spacing: -0.03em;
       }

       .section__intro {
         color: var(--muted);
         max-width: 58ch;
         margin: 0;
       }

       .section__link {
         white-space: nowrap;
         color: var(--accent-strong);
         text-decoration: none;
         font-weight: 700;
       }

       .feature-list,
       .deal-list {
         display: grid;
         gap: 1rem;
       }

       .feature-list {
         grid-template-columns: repeat(4, minmax(0, 1fr));
       }

       .deal-list {
         grid-template-columns: repeat(3, minmax(0, 1fr));
       }

       .product-card,
       .deal-card,
       .editorial-card {
         display: flex;
         flex-direction: column;
         min-height: 100%;
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         background: var(--surface);
         box-shadow: 0 8px 30px rgba(31, 35, 40, 0.06);
         overflow: hidden;
       }

       .product-card__media,
       .deal-card__media,
       .editorial-card__media {
         aspect-ratio: 4 / 3;
         background: var(--surface-2);
       }

       .product-card__body,
       .deal-card__body,
       .editorial-card__body {
         display: flex;
         flex-direction: column;
         gap: 0.85rem;
         padding: 1rem;
         flex: 1;
       }

       .product-card__title,
       .deal-card__title,
       .editorial-card__title {
         margin: 0;
         font-size: 1.05rem;
         line-height: 1.2;
       }

       .product-card__link,
       .deal-card__link,
       .editorial-card__link {
         text-decoration: none;
         color: inherit;
       }

       .product-card__link:hover,
       .deal-card__link:hover,
       .editorial-card__link:hover {
         text-decoration: underline;
         text-decoration-thickness: 0.1em;
         text-underline-offset: 0.2em;
       }

       .meta-list {
         display: flex;
         flex-wrap: wrap;
         gap: 0.5rem;
       }

       .meta-list li {
         padding: 0.35rem 0.55rem;
         border-radius: 999px;
         background: rgba(15, 118, 110, 0.09);
         color: var(--accent-strong);
         font-size: 0.82rem;
         font-weight: 700;
       }

       .price-row {
         display: flex;
         align-items: baseline;
         justify-content: space-between;
         gap: 1rem;
       }

       .price {
         font-size: 1.2rem;
         font-weight: 800;
       }

       .compare {
         color: var(--muted);
         text-decoration: line-through;
         font-size: 0.95rem;
       }

       .product-card__actions {
         display: flex;
         gap: 0.75rem;
         margin-top: auto;
       }

       .product-card__actions .button {
         flex: 1;
       }

       .button--ghost {
         background: transparent;
         border-color: var(--border);
         color: var(--text);
       }

       .button--ghost:hover {
         background: rgba(31, 35, 40, 0.04);
       }

       .deal-card {
         background:
           linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0.94)),
           var(--surface);
       }

       .deal-kicker {
         color: var(--gold);
         font-weight: 800;
         letter-spacing: 0.03em;
         text-transform: uppercase;
         font-size: 0.78rem;
       }

       .deal-savings {
         display: inline-flex;
         width: fit-content;
         border-radius: 999px;
         background: #fef3c7;
         color: #92400e;
         padding: 0.4rem 0.6rem;
         font-weight: 800;
         font-size: 0.84rem;
       }

       .editorial-grid {
         display: grid;
         grid-template-columns: 1.1fr 0.9fr;
         gap: 1rem;
       }

       .editorial-card--feature {
         min-height: 100%;
       }

       .editorial-card__meta {
         color: var(--muted);
         font-size: 0.92rem;
       }

       .story-list {
         display: grid;
         gap: 1rem;
       }

       .story-item {
         display: flex;
         gap: 1rem;
         align-items: flex-start;
         padding: 1rem;
         border-radius: var(--radius-md);
         border: 1px solid var(--border);
         background: var(--surface);
       }

       .story-item__thumb {
         width: 5.5rem;
         aspect-ratio: 1;
         border-radius: 16px;
         object-fit: cover;
         flex-shrink: 0;
       }

       .story-item h3 {
         margin-bottom: 0.35rem;
         font-size: 1rem;
       }

       .story-item p {
         margin-bottom: 0.7rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .story-item a {
         color: var(--accent-strong);
         text-decoration: none;
         font-weight: 700;
       }

       .status-bar {
         margin: 1.5rem 0 0;
         padding: 0.95rem 1rem;
         border-radius: var(--radius-md);
         border: 1px solid var(--border);
         background: var(--surface);
         color: var(--muted);
       }

       .footer {
         margin-top: 2rem;
         padding: 1.75rem 0 2.5rem;
         border-top: 1px solid var(--border);
       }

       .footer__grid {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         flex-wrap: wrap;
       }

       .footer__copy {
         color: var(--muted);
         margin: 0;
       }

       .footer-nav ul {
         display: flex;
         flex-wrap: wrap;
         gap: 1rem;
       }

       .sr-only {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       .icon {
         width: 1rem;
         height: 1rem;
         flex-shrink: 0;
       }

       @media (max-width: 980px) {
         .topbar__inner,
         .hero__grid,
         .section__header,
         .footer__grid {
           grid-template-columns: 1fr;
           flex-direction: column;
           align-items: start;
         }

         .feature-list,
         .deal-list,
         .editorial-grid {
           grid-template-columns: 1fr 1fr;
         }
       }

       @media (max-width: 760px) {
         .primary-nav ul {
           gap: 0.9rem;
         }

         .feature-list,
         .deal-list,
         .editorial-grid {
           grid-template-columns: 1fr;
         }

         .product-card__actions {
           flex-direction: column;
         }

         .story-item {
           flex-direction: column;
         }

         .story-item__thumb {
           width: 100%;
           aspect-ratio: 16 / 10;
         }
       }

       @media (prefers-reduced-motion: no-preference) {
         .button,
         .brand,
         .product-card,
         .deal-card,
         .editorial-card {
           transition:
             transform 160ms ease,
             box-shadow 160ms ease,
             background-color 160ms ease,
             border-color 160ms ease;
         }

         .button:hover,
         .product-card:hover,
         .deal-card:hover,
         .editorial-card:hover {
           transform: translateY(-2px);
         }
       }

       @media (forced-colors: active) {
         :root {
           --border: CanvasText;
         }

         body,
         .topbar,
         .hero__panel,
         .product-card,
         .deal-card,
         .editorial-card,
         .story-item,
         .status-bar,
         .cart-pill {
           forced-color-adjust: auto;
           background: Canvas;
           color: CanvasText;
           border-color: CanvasText;
           box-shadow: none;
         }

         .button--primary,
         .brand__mark,
         .deal-savings,
         .eyebrow,
         .meta-list li {
           forced-color-adjust: auto;
           background: Canvas;
           color: CanvasText;
           border: 1px solid CanvasText;
         }
       }
     </style>
   </head>
