       const createSvgCard = (image, alt) => {
         const img = document.createElement("img");
         img.className = "product-card__media";
         img.src = image;
         img.alt = alt;
         return img;
       };

       const featuredList = document.getElementById("featured-list");
       const dealList = document.getElementById("deal-list");
       const status = document.getElementById("status");
       const cartButton = document.querySelector(".cart-pill");
       let cartCount = 0;

       featuredProducts.forEach((product) => {
         const card = document.createElement("article");
         card.className = "product-card";
         card.innerHTML = `
           <div class="product-card__media-wrap"></div>
         `;

         const mediaWrap = card.querySelector(".product-card__media-wrap");
         mediaWrap.appendChild(createSvgCard(product.image, product.name));

         const body = document.createElement("div");
         body.className = "product-card__body";
         body.innerHTML = `
           <ul class="meta-list" aria-label="${product.name} highlights">
             <li>${product.label}</li>
             <li>Rated ${product.rating} / 5</li>
           </ul>
           <div>
             <h3 class="product-card__title">
               <a class="product-card__link" href="${product.href}">${product.name}</a>
             </h3>
             <div class="price-row">
               <span class="price">${product.price}</span>
               <span class="compare">Was ${product.compareAt}</span>
             </div>
           </div>
           <div class="product-card__actions">
             <button class="button button--primary js-add-to-cart" type="button" data-product="${product.name}">Add to cart</button>
             <button class="button button--ghost" type="button" aria-label="Save ${product.name}">Save</button>
           </div>
         `;

         card.appendChild(body);
         featuredList.appendChild(card);
       });

       deals.forEach((deal) => {
         const card = document.createElement("article");
         card.className = "deal-card";
         card.innerHTML = `
           <div class="deal-card__body">
             <span class="deal-savings">${deal.savings}</span>
             <div>
               <p class="deal-kicker">Deal of the week</p>
               <h3 class="deal-card__title"><a class="deal-card__link" href="${deal.link}">${deal.title}</a></h3>
               <p class="section__intro">${deal.description}</p>
             </div>
             <a class="section__link" href="${deal.link}">Shop deal</a>
           </div>
         `;
         dealList.appendChild(card);
       });

       document.addEventListener("click", (event) => {
         const button = event.target.closest(".js-add-to-cart");
         if (!button) return;

         const product = button.dataset.product;
         cartCount += 1;
         cartButton.innerHTML = `Cart <span aria-hidden="true">${cartCount}</span>`;
         cartButton.setAttribute("aria-label", `Cart, ${cartCount} item${cartCount === 1 ? "" : "s"}`);
         status.textContent = `${product} added to your cart. ${cartCount} item${cartCount === 1 ? "" : "s"} total.`;
       });
     </script>
   </body>
 </html>

')
